const SwitchesJSON = "{\"mail-disabled\":{\"storage\":{\"marker\":\"mail-disabled\"},\"default\":\"absent: mail is delivered\",\"owner\":\"C5\",\"meaning\":\"No mail is delivered and no run is dispatched while it stands; queued mail waits.\",\"writer\":\"hand-only\"},\"coordinator-paused\":{\"storage\":{\"marker\":\"coordinator-paused\"},\"default\":\"absent: coordination runs\",\"owner\":\"C5\",\"meaning\":\"Coordination is paused fleet-wide: no run is dispatched, and no coordinator can lift it itself.\",\"writer\":\"ccd coord-pause, through POST /api/coord/pause\"},\"reclaim-paused\":{\"storage\":{\"marker\":\"reclaim-paused\"},\"default\":\"absent: reclamation runs\",\"owner\":\"C4\",\"meaning\":\"Cleanup is paused fleet-wide: no workspace is reclaimed, expired or collected while it stands.\",\"writer\":\"ccd reclaim-pause, through POST /api/coord/reclaim-pause\"},\"asks-disabled\":{\"storage\":{\"marker\":\"asks-disabled\"},\"default\":\"absent: asks may be held\",\"owner\":\"C6\",\"meaning\":\"No new ask is held back; an ask already held still waits out its own time.\",\"writer\":\"hand-only\"},\"stop-done-disabled\":{\"storage\":{\"marker\":\"stop-done-disabled\"},\"default\":\"absent: the lane runs (it ships live)\",\"owner\":\"C4\",\"meaning\":\"The lane that stops a worker whose run is done does nothing at all.\",\"writer\":\"hand-only\"},\"hibernate-disabled\":{\"storage\":{\"marker\":\"hibernate-disabled\"},\"default\":\"absent: the sweep runs\",\"owner\":\"C4\",\"meaning\":\"The hibernation sweep does nothing at all; it wins over the live switch.\",\"writer\":\"hand-only\"},\"hibernate-live\":{\"storage\":{\"marker\":\"hibernate-live\"},\"default\":\"absent: shadow, nothing is put to sleep\",\"owner\":\"C4\",\"meaning\":\"Hibernation acts: a long-idle session is put to sleep.\",\"writer\":\"hand-only\"},\"expire-lane-live\":{\"storage\":{\"marker\":\"expire-lane-live\"},\"default\":\"absent: shadow, the lane records what it would expire\",\"owner\":\"C4\",\"meaning\":\"The expiry lane acts: an archived workspace past its time is expired.\",\"writer\":\"hand-only\"},\"expire-child-live\":{\"storage\":{\"marker\":\"expire-child-live\"},\"default\":\"absent: shadow, the lane records which archived children it would expire\",\"owner\":\"C4\",\"meaning\":\"The expiry lane takes an archived child too, once the lane itself acts.\",\"writer\":\"hand-only\"},\"stale-archive-live\":{\"storage\":{\"marker\":\"stale-archive-live\"},\"default\":\"absent: shadow, the arm records what it would archive\",\"owner\":\"C4\",\"meaning\":\"The stale-archive arm acts: a workspace with no pane for 14 days is archived.\",\"writer\":\"hand-only\"},\"collect-lane-live\":{\"storage\":{\"marker\":\"collect-lane-live\"},\"default\":\"absent: the Settings arm alone decides\",\"owner\":\"C4\",\"meaning\":\"The legacy arm of the collector: it arms the lane while it stands and its latch is unset.\",\"writer\":\"hand-only\"},\"orphan-tree-live\":{\"storage\":{\"marker\":\"orphan-tree-live\"},\"default\":\"absent: shadow, the lane records what it would remove\",\"owner\":\"C4\",\"meaning\":\"The orphan-worktree lane acts: a clean tree no registry row names, whose commits are all on a remote, is removed.\",\"writer\":\"hand-only\"},\"orphan-tree-rescue-live\":{\"storage\":{\"marker\":\"orphan-tree-rescue-live\"},\"default\":\"absent: a tree with commits on no remote is left\",\"owner\":\"C4\",\"meaning\":\"With the orphan lane live, a tree whose HEAD is on no remote is pinned into the attic and then removed.\",\"writer\":\"hand-only\"},\"collect-loose-live\":{\"storage\":{\"marker\":\"collect-loose-live\"},\"default\":\"absent: shadow, the lane records what loose entries it would remove\",\"owner\":\"C4\",\"meaning\":\"The collector's loose arm acts: an idle entry under the fleet temp directory that no session witnessed is removed, once the lane itself is live.\",\"writer\":\"hand-only\"},\"dead-coordinator-lane-live\":{\"storage\":{\"marker\":\"dead-coordinator-lane-live\"},\"default\":\"absent: shadow, the lane records what it would end\",\"owner\":\"C5\",\"meaning\":\"The dead-coordinator lane acts: a programme whose coordinator is gone is ended.\",\"writer\":\"hand-only\"},\"runs-expire-never-started\":{\"storage\":{\"marker\":\"runs-expire-never-started\"},\"default\":\"absent: shadow, the lane records what it would warn and close\",\"owner\":\"C5\",\"meaning\":\"The run-close lane closes never-started waves in a quiet programme.\",\"writer\":\"hand-only\"},\"runs-expire-coordinator-gone\":{\"storage\":{\"marker\":\"runs-expire-coordinator-gone\"},\"default\":\"absent: shadow, the lane records what it would close\",\"owner\":\"C5\",\"meaning\":\"The run-close lane closes the runs of a coordinator that was removed or stopped by a person, and runs whose session name a later run reuses.\",\"writer\":\"hand-only\"},\"nested-rescue-live\":{\"storage\":{\"marker\":\"nested-rescue-live\"},\"default\":\"absent: shadow, a nested repository is refused and the audit names what the arm would rescue\",\"owner\":\"C4\",\"meaning\":\"Rung 9 rescues a nested repository into the attic instead of refusing a tree that holds one.\",\"writer\":\"hand-only\"},\"drift-push-live\":{\"storage\":{\"marker\":\"drift-push-live\"},\"default\":\"absent: shadow, the reconciler records what it would push\",\"owner\":\"C5\",\"meaning\":\"The drift reconciler pushes the operator once about a finding that stands past 24 hours. Arm it only once the digest lists drift findings: its summary push opens the day's digest.\",\"writer\":\"hand-only\"},\"child-reclaim-disabled\":{\"storage\":{\"marker\":\"child-reclaim-disabled\"},\"default\":\"absent: child reclaim runs\",\"owner\":\"C4\",\"meaning\":\"Switches off child reclaim alone: the sweep and the close hand-off queue none, and the executor refuses to act. Expiry, collect, the dead-coordinator lane and stop-done keep running; reclaim-paused stops those too.\",\"writer\":\"hand-only\"},\"child-stale-reclaim-live\":{\"storage\":{\"marker\":\"child-stale-reclaim-live\"},\"default\":\"absent: shadow, the lane records what it would reclaim\",\"owner\":\"C4\",\"meaning\":\"The stale arm acts: a kept child idle for seven days is reclaimed, its work pinned to the attic.\",\"writer\":\"hand-only\"},\"deps-shed-live\":{\"storage\":{\"marker\":\"deps-shed-live\"},\"default\":\"absent: shadow, the arm records what it would remove\",\"owner\":\"C4\",\"meaning\":\"The deps-shed arm acts: a sleeping worker or coordinator whose work finished past the age has its ignored dependency directories removed; its worktree and every git fact stay.\",\"writer\":\"hand-only\"},\"child-superseded-reclaim-live\":{\"storage\":{\"marker\":\"child-superseded-reclaim-live\"},\"default\":\"absent: shadow, the lane records what it would reclaim\",\"owner\":\"C4\",\"meaning\":\"An earlier review child is reclaimed once a later review of the same run has closed, though the reviewed run is still open.\",\"writer\":\"hand-only\"},\"idle-compact-nudge-disabled\":{\"storage\":{\"marker\":\"idle-compact-nudge-disabled\"},\"default\":\"absent: the nudge runs\",\"owner\":\"C3\",\"meaning\":\"A session left idle after compaction with work open is not nudged.\",\"writer\":\"hand-only\"},\"autocompact-disabled\":{\"storage\":{\"marker\":\"autocompact-disabled\"},\"default\":\"absent: ccd compacts an idle session whose context reaches its threshold\",\"owner\":\"C3\",\"meaning\":\"ccd never types /compact into an idle session, fleet-wide, however full its context is.\",\"writer\":\"hand-only\"},\"graph-gate-off\":{\"storage\":{\"ccrcFile\":\"graph-gate-off\"},\"default\":\"absent: a search in a freshly graphed tree is turned back until the session queries the graph\",\"owner\":\"C3\",\"meaning\":\"The graph gate is open: no session is turned back to query its tree's code graph before it searches.\",\"writer\":\"hand-only\"},\"ccrc-card-off\":{\"storage\":{\"ccrcFile\":\"ccrc-card-off\"},\"default\":\"absent: a session's context carries the hold card and the ccrc card\",\"owner\":\"C5\",\"meaning\":\"The session hook prints neither the hold card nor the ccrc card; the graphify card is unaffected.\",\"writer\":\"hand-only\"},\"compact-card-off\":{\"storage\":{\"ccrcFile\":\"compact-card-off\"},\"default\":\"absent: the compaction card runs\",\"owner\":\"C3\",\"meaning\":\"The compaction card is off in all three of its arms: no card, no steering and no measurement around a compaction.\",\"writer\":\"hand-only\"},\"ccd-entry-timing\":{\"storage\":{\"marker\":\"ccd-entry-timing\"},\"default\":\"absent: nothing is timed\",\"owner\":\"C2\",\"meaning\":\"The ccd launcher logs each run's verb, duration and status to ~/.ccrc/ccd-entry-timing.log.\",\"writer\":\"hand-only\"},\"ccd-go-off\":{\"storage\":{\"marker\":\"ccd-go-off\"},\"default\":\"absent: listed verbs start the Go core\",\"owner\":\"C2\",\"meaning\":\"Empty: every verb starts bash. One verb per line: those verbs start bash.\",\"writer\":\"hand-only\"},\"mail-gate-strict\":{\"storage\":{\"marker\":\"mail-gate-strict\"},\"default\":\"absent: the shell mode\",\"owner\":\"C5\",\"meaning\":\"Mail is delivered only to an idle session, the rule before the gate's first wave, whatever else stands.\",\"writer\":\"hand-only\"},\"mail-gate-busy\":{\"storage\":{\"marker\":\"mail-gate-busy\"},\"default\":\"absent: the shell mode\",\"owner\":\"C5\",\"meaning\":\"Mail is delivered to a busy session whose main turn has ended.\",\"writer\":\"hand-only\"},\"mail-gate-busy-shadow\":{\"storage\":{\"marker\":\"mail-gate-busy-shadow\"},\"default\":\"absent: the shell mode\",\"owner\":\"C5\",\"meaning\":\"The gate decides busy as the busy mode would, delivers nothing more, and logs what it would have sent.\",\"writer\":\"hand-only\"},\"stall-watch-disabled\":{\"storage\":{\"marker\":\"stall-watch-disabled\"},\"default\":\"absent: the watch runs at the level that applies\",\"owner\":\"C5\",\"meaning\":\"The worker stall watch does nothing at all: nothing is recorded or sent, whatever level is chosen in Settings.\",\"writer\":\"hand-only\"},\"coordinator-roster-card-live\":{\"storage\":{\"marker\":\"coordinator-roster-card-live\"},\"default\":\"absent: shadow, the card goes to ~/.ccrc/roster-card-shadow.log\",\"owner\":\"C5\",\"meaning\":\"A coordinator's first context after a compaction, resume or clear, and its first wake after an idle compaction, carries the open runs it claims.\",\"writer\":\"hand-only\"},\"landing-disabled\":{\"storage\":{\"marker\":\"landing-disabled\"},\"default\":\"absent: the checks lane reads and writes its rows\",\"owner\":\"C4\",\"meaning\":\"The PR-landing checks lane makes no read and writes no edge or mail; it wins over the live marker, and a live episode keeps only its stuck bound.\",\"writer\":\"hand-only\"},\"landing-checks-live\":{\"storage\":{\"marker\":\"landing-checks-live\"},\"default\":\"absent: new episodes run in shadow, nothing is mailed\",\"owner\":\"C4\",\"meaning\":\"New PR-landing episodes are live: the checks lane mails the coordinator when the required checks settle.\",\"writer\":\"hand-only\"},\"stall-watch-level\":{\"storage\":{\"setting\":\"stall_settings.level\"},\"default\":\"follow\",\"owner\":\"C5\",\"meaning\":\"How far the worker stall watch acts, chosen in Settings.\",\"writer\":\"POST /api/coord/stall-watch\"},\"collect-lane-choice\":{\"storage\":{\"setting\":\"collect_lane_settings.choice\"},\"default\":\"off\",\"owner\":\"C4\",\"meaning\":\"The Settings arm of the collector: only an exact live choice arms it.\",\"writer\":\"POST /api/coord/collect-lane\"},\"roll-idle-targets\":{\"storage\":{\"setting\":\"roll_settings.targets\"},\"default\":\"coordinators\",\"owner\":\"C4\",\"meaning\":\"Which idle sessions the automatic roll restarts onto the current release: coordinators, or off (D-7453).\",\"writer\":\"POST /api/coord/roll-idle\"},\"dispatch-abandon-choice\":{\"storage\":{\"setting\":\"dispatch_abandon_settings.choice\"},\"default\":\"on\",\"owner\":\"C5\",\"meaning\":\"The server abandons a run whose dispatch never came back and mails its coordinator: on, or off (D-7319).\",\"writer\":\"POST /api/coord/dispatch-abandon\"},\"run-close-never-started-choice\":{\"storage\":{\"setting\":\"run_close_settings.neverStarted\"},\"default\":\"shadow\",\"owner\":\"C5\",\"meaning\":\"The run-close lane's never-started group (rows E1 and E1r): off, shadow (it records what it would close) or on (D-8077). A standing runs-expire-never-started marker is an emergency override that arms it.\",\"writer\":\"POST /api/coord/run-close\"},\"run-close-claimant-crashed-choice\":{\"storage\":{\"setting\":\"run_close_settings.claimantCrashed\"},\"default\":\"shadow\",\"owner\":\"C5\",\"meaning\":\"The crash row of the run-close lane (a claimant that crashed): off, shadow or on (D-8077). A standing dead-coordinator-lane-live marker is an emergency override that arms it.\",\"writer\":\"POST /api/coord/run-close\"},\"run-close-claimant-gone-choice\":{\"storage\":{\"setting\":\"run_close_settings.claimantGone\"},\"default\":\"shadow\",\"owner\":\"C5\",\"meaning\":\"The claimant-gone group of the run-close lane (rows E3, E3s and E5): off, shadow (it records what it would close) or on (D-8078). A standing runs-expire-coordinator-gone marker is an emergency override that arms it.\",\"writer\":\"POST /api/coord/run-close\"},\"plain-auto-memory\":{\"storage\":{\"setting\":\"plain_memory_settings.choice\"},\"default\":\"off\",\"owner\":\"C3\",\"meaning\":\"Whether a session that is neither a coordinator nor a dispatched worker keeps Claude Code's auto memory at its next launch: off, or on.\",\"writer\":\"POST /api/coord/plain-auto-memory\"},\"overlord-rung\":{\"storage\":{\"setting\":\"overlord_ladder.operatorRung\"},\"default\":\"chat\",\"owner\":\"C5\",\"meaning\":\"The operator's rung of the Overlord's ladder: off, chat, advise or full. The effective rung is never above it.\",\"writer\":\"POST /api/overlord/rung and POST /api/overlord/pause; Confirm the restore writes its stricter value\"},\"scope-sweep-live\":{\"storage\":{\"marker\":\"scope-sweep-live\"},\"default\":\"absent: shadow, the sweep records what it would stop\",\"owner\":\"C4\",\"meaning\":\"The pane-scope sweep acts: an inert scope of a dead pane is stopped, three a minute at most.\",\"writer\":\"hand-only\"},\"scope-sweep-busy-live\":{\"storage\":{\"marker\":\"scope-sweep-busy-live\"},\"default\":\"absent: shadow, the sweep records the busy scopes it would stop\",\"owner\":\"C4\",\"meaning\":\"With the sweep itself live, a busy scope whose session has been provably dead for six hours is stopped too, inside the same three a minute.\",\"writer\":\"ccd scope-sweep-busy, through POST /api/coord/scope-sweep\"},\"delegation-adopt\":{\"storage\":{\"marker\":\"delegation-adopt\"},\"default\":\"absent: shadow, the lane records what it would adopt\",\"owner\":\"C5\",\"meaning\":\"The delegation lane adopts a changed worktree whose delegated activity has terminal evidence, and mails its owner.\",\"writer\":\"ccd delegation-adopt, through POST /api/coord/delegation-adopt\"},\"pane-scope-stop-live\":{\"storage\":{\"marker\":\"pane-scope-stop-live\"},\"default\":\"absent: shadow, a stop only logs what it would stop\",\"owner\":\"C2\",\"meaning\":\"A session stopped on purpose (a stop, a finished worker, a sleep) also stops what it left running in its pane, once its main process has exited.\",\"writer\":\"ccd pane-scope-stop, through POST /api/coord/pane-scope-stop\"},\"testbox-remote-live\":{\"storage\":{\"marker\":\"testbox-remote-live\"},\"default\":\"absent: every run is local\",\"owner\":\"C2\",\"meaning\":\"Test runs go to the test box when its checks pass; any run that cannot falls back to the local tests slice and says why.\",\"writer\":\"ccd testbox-remote, through POST /api/testbox/switch\"}}"

